'use strict';

// Extracts the exposable API (classes, attributes, events) from the C++ sources generated by Rhapsody.
// It relies only on the markers Rhapsody always writes ("//## class", "//## attribute",
// "//## event", "//## package") so that any model change is picked up without touching this code.

// Replaces comments and string/char literals by spaces (same length, newlines kept) so that
// brace matching and regex searches cannot be fooled by their content.
function maskCode(text) {
  const out = text.split('');
  const n = text.length;
  let i = 0;
  const blank = (from, to) => {
    for (let k = from; k < to && k < n; k++) if (out[k] !== '\n' && out[k] !== '\r') out[k] = ' ';
  };
  while (i < n) {
    const ch = text[i];
    const next = text[i + 1];
    if (ch === '/' && next === '/') {
      let j = i;
      while (j < n && text[j] !== '\n') j++;
      blank(i, j);
      i = j;
    } else if (ch === '/' && next === '*') {
      const end = text.indexOf('*/', i + 2);
      const stop = end === -1 ? n : end + 2;
      blank(i, stop);
      i = stop;
    } else if (ch === '"' || ch === "'") {
      let j = i + 1;
      while (j < n && text[j] !== ch && text[j] !== '\n') {
        if (text[j] === '\\') j++;
        j++;
      }
      blank(i + 1, j);
      i = j + 1;
    } else {
      i++;
    }
  }
  return out.join('');
}

function matchingBrace(masked, open) {
  let depth = 0;
  for (let i = open; i < masked.length; i++) {
    if (masked[i] === '{') depth++;
    else if (masked[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

const INT_TYPES = new Set([
  'char', 'signed char', 'unsigned char', 'short', 'short int', 'signed short', 'unsigned short', 'unsigned short int',
  'int', 'signed', 'signed int', 'unsigned', 'unsigned int', 'long', 'long int', 'signed long', 'unsigned long', 'unsigned long int',
  'long long', 'long long int', 'unsigned long long', 'unsigned long long int', '__int64', 'unsigned __int64',
  'int8_t', 'int16_t', 'int32_t', 'int64_t', 'uint8_t', 'uint16_t', 'uint32_t', 'uint64_t',
  'size_t', 'ptrdiff_t', 'intptr_t', 'uintptr_t', 'BYTE', 'WORD', 'DWORD', 'UINT', 'ULONG', 'LONG', 'SHORT', 'USHORT', 'UCHAR', 'INT',
]);
const FLOAT_TYPES = new Set(['float', 'double', 'long double']);
const STRING_TYPES = new Set(['OMString', 'string']);
const BOOL_TYPES = new Set(['bool', '_Bool']);

function normalizeType(text) {
  return text
    .replace(/\b(static|const|volatile|mutable|extern|constexpr|register)\b/g, ' ')
    .replace(/\bstd::/g, '')
    .replace(/&/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Returns { kind, cppType, enumName? } or null when the type cannot be exposed.
function classify(typeText, ctx) {
  let t = normalizeType(typeText);
  if (ctx.typeMap && ctx.typeMap[t]) t = normalizeType(ctx.typeMap[t]);
  if (!t || /[*<>()]/.test(t)) return null;
  if (BOOL_TYPES.has(t)) return { kind: 'bool', cppType: t };
  if (FLOAT_TYPES.has(t)) return { kind: 'float', cppType: t };
  if (INT_TYPES.has(t)) return { kind: 'int', cppType: t };
  if (STRING_TYPES.has(t)) return { kind: 'string', cppType: t === 'string' ? 'std::string' : t };
  const bare = t.replace(/^(enum|struct|class)\s+/, '');
  if (ctx.enums && ctx.enums.has(bare)) return { kind: 'int', cppType: bare, enumName: bare };
  return null;
}

function splitTopLevel(text, sep = ',') {
  const parts = [];
  let depth = 0;
  let cur = '';
  for (const ch of text) {
    if ('(<[{'.includes(ch)) depth++;
    else if (')>]}'.includes(ch)) depth--;
    if (ch === sep && depth === 0) {
      parts.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }
  if (cur.trim()) parts.push(cur);
  return parts.map((p) => p.trim()).filter(Boolean);
}

function resolveDim(expr, defines) {
  const e = expr.trim();
  if (/^\d+$/.test(e)) return Number(e);
  if (defines.has(e)) return defines.get(e);
  return null; // unknown at generation time (the C++ code still handles it)
}

function parseDims(text, defines) {
  const dims = [];
  const re = /\[([^\]]*)\]/g;
  let m;
  while ((m = re.exec(text))) dims.push(resolveDim(m[1], defines));
  return dims;
}

function lineStart(text, index) {
  return text.lastIndexOf('\n', index - 1) + 1;
}

function collectGlobals(files) {
  const defines = new Map();
  const enums = new Set();
  for (const f of files) {
    const masked = f.masked;
    for (const m of masked.matchAll(/^[ \t]*#[ \t]*define[ \t]+(\w+)[ \t]+(\d+)[ \t]*$/gm)) defines.set(m[1], Number(m[2]));
    for (const m of masked.matchAll(/\benum\s+(?:class\s+|struct\s+)?(\w+)\s*(?::\s*[\w ]+)?\{/g)) enums.add(m[1]);
    for (const m of masked.matchAll(/\btypedef\s+enum\s*\w*\s*\{[^}]*\}\s*(\w+)\s*;/g)) enums.add(m[1]);
  }
  return { defines, enums };
}

function parseClasses(file, ctx, model) {
  const { text, masked } = file;
  const markerRe = /^[ \t]*\/\/##[ \t]*class[ \t]+(\w+)/gm;
  let marker;
  while ((marker = markerRe.exec(text))) {
    const name = marker[1];
    const declRe = new RegExp(`\\b(class|struct)\\s+${name}\\b\\s*(?::([^{;]*))?\\{`, 'g');
    declRe.lastIndex = marker.index;
    const decl = declRe.exec(masked);
    if (!decl || decl.index - marker.index > 3000) {
      model.warnings.push(`${file.name}: "//## class ${name}" found but no matching class declaration`);
      continue;
    }
    const open = decl.index + decl[0].length - 1;
    const close = matchingBrace(masked, open);
    if (close < 0) {
      model.warnings.push(`${file.name}: unbalanced braces in class ${name}`);
      continue;
    }
    const bases = (decl[2] || '').split(',').map((b) => b.replace(/\b(public|protected|private|virtual)\b/g, '').trim()).filter(Boolean);
    const cls = {
      name,
      file: file.name,
      bases,
      reactive: false,
      attributes: [],
      markerIndex: lineStart(text, marker.index),
      closeIndex: close,
      keyword: decl[1],
    };
    parseAttributes(file, cls, open, close, ctx, model);
    model.classes.push(cls);
  }
}

function parseAttributes(file, cls, open, close, ctx, model) {
  const { text, masked } = file;
  let access = cls.keyword === 'struct' ? 'public' : 'private';
  const body = text.slice(open + 1, close);
  const maskedBody = masked.slice(open + 1, close);
  const lines = body.split('\n');
  const maskedLines = maskedBody.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const acc = /^\s*(public|protected|private)\s*:/.exec(maskedLines[i]);
    if (acc) access = acc[1];
    const m = /^(.*?)\s*;\s*\/\/##[ \t]*attribute[ \t]+(\w+)/.exec(lines[i]);
    if (!m) continue;
    const name = m[2];
    let decl = m[1].trim();
    const eq = decl.indexOf('=');
    if (eq >= 0 && !decl.slice(0, eq).includes('[')) decl = decl.slice(0, eq).trim();
    else if (eq >= 0) decl = decl.replace(/\s*=.*$/, '');
    const dm = new RegExp(`^(.*?)\\b${name}\\b\\s*((?:\\[[^\\]]*\\]\\s*)*)$`).exec(decl);
    if (!dm || !dm[1].trim()) {
      model.unsupported.push({ kind: 'attribute', class: cls.name, name, type: decl, reason: 'declaration not understood' });
      continue;
    }
    const typeText = dm[1];
    const dims = parseDims(dm[2], ctx.defines);
    const isStatic = /\bstatic\b/.test(typeText);
    const isConst = /\bconst\b/.test(typeText) || /\bconstexpr\b/.test(typeText);
    let cls_ = classify(typeText, ctx);
    let finalDims = dims;
    if (cls_ && cls_.cppType === 'char' && dims.length === 1) {
      cls_ = { kind: 'string', cppType: `char[${dims[0] === null ? '' : dims[0]}]`, maxLength: dims[0] === null ? null : dims[0] - 1 };
      finalDims = [];
    }
    if (!cls_) {
      model.unsupported.push({ kind: 'attribute', class: cls.name, name, type: normalizeType(typeText) + dm[2].replace(/\s+/g, ''), reason: 'unsupported type' });
      continue;
    }
    cls.attributes.push({
      name,
      type: cls_.cppType.startsWith('char[') ? cls_.cppType : normalizeType(typeText) + dm[2].replace(/\s+/g, ''),
      cppType: cls_.cppType,
      kind: cls_.kind,
      dims: finalDims,
      writable: !isConst,
      static: isStatic,
      const: isConst,
      access,
      ...(cls_.enumName ? { enumName: cls_.enumName } : {}),
      ...(cls_.maxLength !== undefined ? { maxLength: cls_.maxLength } : {}),
    });
  }
}

function parseEvents(file, ctx, model) {
  const { text, masked } = file;
  const markerRe = /^[ \t]*\/\/##[ \t]*event[ \t]+(\w+)[ \t]*\(([^)]*)\)/gm;
  let marker;
  while ((marker = markerRe.exec(text))) {
    const name = marker[1];
    const declRe = new RegExp(`\\bclass\\s+${name}\\b\\s*(?::([^{;]*))?\\{`, 'g');
    declRe.lastIndex = marker.index;
    const decl = declRe.exec(masked);
    if (!decl || decl.index - marker.index > 500) {
      model.warnings.push(`${file.name}: "//## event ${name}" found but no matching class declaration`);
      continue;
    }
    const open = decl.index + decl[0].length - 1;
    const close = matchingBrace(masked, open);
    const body = masked.slice(open + 1, close);
    const ctorRe = new RegExp(`(?<![~\\w])${name}\\s*\\(([^)]*)\\)\\s*;`, 'g');
    let best = '';
    let ctor;
    while ((ctor = ctorRe.exec(body))) {
      if (splitTopLevel(ctor[1]).length >= splitTopLevel(best).length) best = ctor[1];
    }
    const pkgMatches = [...text.slice(0, marker.index).matchAll(/\/\/##[ \t]*package[ \t]+(\w+)/g)];
    const pkg = pkgMatches.length ? pkgMatches[pkgMatches.length - 1][1] : '';
    const args = [];
    let supported = true;
    splitTopLevel(best).forEach((param, idx) => {
      const p = param.replace(/\s*=.*$/, '').trim();
      let typeText = p;
      let argName = `arg${idx}`;
      // "type name" (the name is optional in C++ declarations, e.g. "double" alone is a valid parameter)
      if (!classify(p, ctx)) {
        const pm = /^(.*?)(\w+)\s*$/.exec(p);
        if (pm && pm[1].trim()) {
          typeText = pm[1];
          argName = pm[2].replace(/^p_/, '');
        }
      }
      const k = classify(typeText, ctx);
      if (!k) {
        supported = false;
        model.unsupported.push({ kind: 'event', name, type: normalizeType(typeText), reason: `unsupported argument type for "${argName}"` });
        return;
      }
      args.push({ name: argName, type: normalizeType(typeText), cppType: k.cppType, kind: k.kind, ...(k.enumName ? { enumName: k.enumName } : {}) });
    });
    if (!supported) continue;
    const existing = model.events.find((e) => e.name === name);
    if (existing) {
      model.warnings.push(`event "${name}" is defined twice (${existing.file} and ${file.name}); the first definition is used`);
      continue;
    }
    model.events.push({ name, file: file.name, pkg, args, handledBy: [] });
  }
}

// Finds which classes react to which events by looking at IS_EVENT_TYPE_OF(<id>) in the statecharts.
function findEventHandlers(sources, model) {
  const idToEvent = new Map();
  for (const ev of model.events) idToEvent.set(`${ev.name}_${ev.pkg}_id`, ev);
  const classNames = new Set(model.classes.map((c) => c.name));
  for (const f of sources) {
    let current = null;
    for (const line of f.masked.split('\n')) {
      const def = /^[^\s#/{}][^;]*?\b(\w+)::~?\w+\s*\(/.exec(line);
      if (def) current = def[1];
      const m = /IS_EVENT_TYPE_OF\(\s*(\w+)\s*\)/.exec(line);
      if (!m || !current || !classNames.has(current)) continue;
      const ev = idToEvent.get(m[1]);
      if (ev && !ev.handledBy.includes(current)) ev.handledBy.push(current);
    }
  }
  for (const ev of model.events) ev.handledBy.sort();
}

// files: [{ name, text }] (headers and sources). Returns the raw model of the generated code.
function parseModel(files, { typeMap = {} } = {}) {
  const prepared = files.map((f) => ({ ...f, masked: maskCode(f.text) }));
  const headers = prepared.filter((f) => /\.(h|hpp|hh)$/i.test(f.name));
  const sources = prepared.filter((f) => /\.(c|cpp|cc|cxx)$/i.test(f.name));
  const { defines, enums } = collectGlobals(prepared);
  const ctx = { defines, enums, typeMap };
  const model = { classes: [], events: [], unsupported: [], warnings: [] };

  for (const h of headers) {
    parseClasses(h, ctx, model);
    parseEvents(h, ctx, model);
  }

  const byName = new Map(model.classes.map((c) => [c.name, c]));
  const isReactive = (cls, seen = new Set()) => {
    if (seen.has(cls.name)) return false;
    seen.add(cls.name);
    return cls.bases.some((b) => b === 'OMReactive' || (byName.has(b) && isReactive(byName.get(b), seen)));
  };
  for (const c of model.classes) c.reactive = isReactive(c);

  findEventHandlers(sources, model);
  return model;
}

module.exports = { parseModel, maskCode, classify, splitTopLevel };
